#include <linux/socket.h>
#include <linux/bluetooth.h>

int get_rfcomm_address(struct socket *sock, struct sockaddr *addr, int *len, int peer) {
    struct sockaddr_rc *saddr = (struct sockaddr_rc *)addr;
    struct sock *sk = sock->sk;
    struct bt_sock *bt = bt_sk(sk);
    struct sockaddr_rc src;
    int err;

    if (peer)
        err = sock->ops->getname(sock, (struct sockaddr *)&src, 0);
    else
        src.rc_family = AF_BLUETOOTH;
        bacpy(&src.rc_bdaddr, &bt->src);

    if (err < 0)
        return err;

    saddr->rc_family = src.rc_family;
    bacpy(&saddr->rc_bdaddr, &src.rc_bdaddr);
    saddr->rc_channel = bt->src_channel;

    *len = sizeof(struct sockaddr_rc);
    return 0;
}

#include <net/sock.h>
#include <bluetooth/bluetooth.h>
#include <bluetooth/rfcomm.h>

int get_rfcomm_address(struct socket *sock, struct sockaddr *addr, int *len, int peer)
{
    struct sockaddr_rc *saddr = (struct sockaddr_rc *)addr;
    struct sock *sk = sock->sk;

    saddr->rc_family = AF_BLUETOOTH;
    saddr->rc_channel = sk->sk_rcv_msg_page ? : 0;

    if (peer)
        bacpy(&saddr->rc_bdaddr, &sk->sk_peer_ba);
    else
        bacpy(&saddr->rc_bdaddr, &sk->sk_ba);

    *len = sizeof(*saddr);
    return 0;
}

#include <linux/socket.h>
#include <linux/bluetooth.h>
#include <asm/unaligned.h>

int get_rfcollm_address(struct socket *sock, struct sockaddr *addr, int *len, int peer) {
    struct sockaddr_rc *saddr = (struct sockaddr_rc *)addr;
    struct sock *sk = sock->sk;

    saddr->rc_family = AF_BLUETOOTH;

    if (peer) {
        bacpy(&saddr->rc_bdaddr, &sk->sk_daddr);
        saddr->rc_channel = sk->sk_dport;
    } else {
        bacpy(&saddr->rc_bdaddr, &sk->sk_vifaddr);
        saddr->rc_channel = sk->sk_num;
    }

    *len = sizeof(struct sockaddr_rc);
    return 0;
}
